function space(folder,required,options={}){const stat=fs.statfsSync(folder),available=options.freeBytes??stat.bavail*stat.bsize;check(Number.isFinite(required)&&required>=0&&available>=required,'Not enough free disk space for the backup, staging files and recovery copy.');}
