 check(db.prepare('PRAGMA '+schema+'.application_id').get().application_id===APPLICATION&&db.prepare('PRAGMA '+schema+'.user_version').get().user_version===VERSION,'Choose a supported SlotForge portable backup.');
 const objects=db.prepare("SELECT type,name FROM "+prefix+"sqlite_master WHERE name NOT LIKE 'sqlite_%'").all();check(objects.length===3&&objects.every(x=>x.type==='table'&&['metadata','records','assets'].includes(x.name)),'Unexpected backup database schema.');
 for(const [table,columns]of [['metadata','name,value'],['records','key,json,digest'],['assets','hash,value']]){const info=db.prepare('PRAGMA '+schema+'.table_info('+table+')').all();check(info.map(x=>x.name).join()===columns&&info.every((x,i)=>x.type===(table==='assets'&&i===1?'BLOB':'TEXT')&&x.notnull===1&&x.pk===(i===0?1:0))&&db.prepare('PRAGMA '+schema+'.table_list').all().some(x=>x.name===table&&x.strict===1&&x.ncol===info.length),'Invalid backup table.');}
 check(db.prepare('SELECT count(*) n FROM '+prefix+'metadata').get().n===6,'Invalid backup metadata count.');
 for(const [table,condition]of [['metadata','length(name)>50 OR length(CAST(value AS BLOB))>33554432'],['records','length(key)>2048 OR length(CAST(json AS BLOB))>33554432 OR length(digest)<>64'],['assets','length(hash)<>64 OR length(value)>29360128']])check(!db.prepare('SELECT 1 FROM '+prefix+table+' WHERE '+condition+' LIMIT 1').get(),'Backup row exceeds its format limit.');
